DECLARE packs jsonb := $pack$[{"codigo":"S22P-C01","legacy_id":552,"legacy_ids":[552],"relacionadas":["S13-C07"],"residual":"Falta referencia canónica del número de tarjetas y reconciliación visual exacta; no fijar cardinalidad desde mockup.","coberturas":[{"legacy_id":552,"estado_cobertura":"PARCIAL","residual":"Falta referencia canónica del número de tarjetas y reconciliación visual exacta; no fijar cardinalidad desde mockup.","diferencias":"En HOME_APRENDA_ANTES_DECIDIR BLOQUEAR popup que mantenga semántica paralela a reglas fuente. Tu deuda puede haber cambiado de manos consume EDU-NODO-02-EXPLORA y no publica detalle legal preciso si candidato o claims pendientes; fuente PUBLICABLE requerida. ¿Cómo funciona el simulador? conserva naming decisión 46, explica celular ONB_001, OTP, DNI si corresponde y resolución backend, sin simulación hipotética ni lookup directo. ¿Qué ocurre después de revisar tu opción? consume EDU-NODO-03-ELIGE y EDU-NODO-04-CIERRA, oferta válida pago único/cuotas, confirmación y constancia/carta por deuda tras SETTLED_CONFIRMED, sin plazos SBS históricos no verificados. Cierres comerciales ONB_001; aplicar frescura de claims. Visual mapping PENDING_CANONICAL_VISUAL, PEND-CLIENT-HOME-LEARN-CANONICAL-VISUAL-001. Complementa S13-C07; binding pendiente."}],"hechos":["s22p01_render_aprendizaje","s22p01_fuente_paralela_o_no_publicable","s22p01_flujo_simulador_invalido","s22p01_pago_carta_o_plazo_invalido","s22p01_cierre_comercial_invalido"],"paquete":{"tipo":"NUEVA","codigo":"S22P-C01","clave":"s22p_legacy_552","familia":"UI_MESSAGES","naturaleza":"CONDUCTA","clase":"PANTALLA","alcance":"CLIENT_HOME","modo":"HEREDA","dueno":"PRODUCTO","titulo":"Contenido de aprendizaje derivado de fuentes gobernadas","descripcion":"En HOME_APRENDA_ANTES_DECIDIR BLOQUEAR popup que mantenga semántica paralela a reglas fuente. Tu deuda puede haber cambiado de manos consume EDU-NODO-02-EXPLORA y no publica detalle legal preciso si candidato o claims pendientes; fuente